import { LINK_REFRESH_WINDOW_MS } from './links';

/**
 * Give a rendered preview <img> a real src.
 *
 * Why this is not part of the parse: every stored file classifies as
 * `expired: true` with the _expired_.url placeholder as its href, so the url an
 * <img> needs does not exist until something mints it. agent.vue memoizes its
 * parse on the raw message text and drops that cache whenever its link maps
 * change, so minting THROUGH those maps would clear the whole cache once per
 * image and re-run marked over the entire conversation each time. The mint
 * therefore lives here, in a cache that is not reactive and is never read by the
 * parse, and the src is written straight onto the element after render.
 *
 * DOM-free like the rest of the engine: the element type is structural, so a
 * real HTMLImageElement satisfies it while this file imports nothing from
 * lib.dom and touches no global.
 */

export interface PreviewImageEl {
	getAttribute(name: string): string | null;
	setAttribute(name: string, value: string): void;
	removeAttribute(name: string): void;
	addEventListener(type: string, cb: () => void): void;
}

export interface ImagePreviewContext {
	/** Project id. Namespaces the cache, see clearImagePreviewCache. */
	scope: string;
	/**
	 * Mint a directly loadable url for a storage path.
	 *
	 * `contentType` is not advisory. get_signed_url only sets
	 * ResponseContentType when the caller passes one and otherwise falls back to
	 * application/octet-stream, which a new tab DOWNLOADS instead of displaying.
	 * An implementation that drops this argument still paints the preview (an
	 * <img> sniffs the bytes) but silently breaks the click.
	 */
	mint: (remotePath: string, contentType: string) => Promise<string>;
	/** An image finished painting. Views use it to re-pin the scroll. */
	onLoad?: (remotePath: string) => void;
	/** A preview gave up. The caption chip is now the whole answer. */
	onError?: (remotePath: string, err: unknown) => void;
}

interface MintedPreview { url: string; at: number; }

var previewUrlCache: Record<string, MintedPreview> = Object.create(null);
var previewInFlight: Record<string, Promise<string>> = Object.create(null);

function cacheKey(scope: string, path: string): string { return scope + '�' + path; }

/**
 * Drop cached preview urls, for one project or all of them.
 *
 * The key carries the project because an identity-blind cache is how one
 * project's content has reached another project's chat before. Call on project
 * switch and on sign-out.
 */
export function clearImagePreviewCache(scope?: string): void {
	if (!scope) {
		previewUrlCache = Object.create(null);
		previewInFlight = Object.create(null);
		return;
	}
	var prefix = scope + '�';
	for (var k in previewUrlCache) if (k.indexOf(prefix) === 0) delete previewUrlCache[k];
	for (var f in previewInFlight) if (f.indexOf(prefix) === 0) delete previewInFlight[f];
}

/**
 * A url we already hold that is still comfortably alive, or null.
 *
 * Synchronous on purpose. Both views rebuild bubble DOM constantly (the widget
 * tears down and re-creates every node in renderMessages; Vue re-patches v-html
 * whenever the string changes), so an async-only assignment would blank every
 * visible image for a frame on each re-render. Called before paint, this makes a
 * re-render invisible.
 */
export function peekImagePreviewUrl(ctx: ImagePreviewContext, remotePath: string): string | null {
	var hit = previewUrlCache[cacheKey(ctx.scope, remotePath)];
	// Same headroom the chip cache uses: drop the url before it dies, never after.
	if (hit && Date.now() - hit.at < LINK_REFRESH_WINDOW_MS) return hit.url;
	return null;
}

/** Deduped, TTL-bounded mint for one path. */
export function resolveImagePreviewUrl(
	ctx: ImagePreviewContext,
	remotePath: string,
	contentType: string,
): Promise<string> {
	var warm = peekImagePreviewUrl(ctx, remotePath);
	if (warm) return Promise.resolve(warm);
	var key = cacheKey(ctx.scope, remotePath);
	var flight = previewInFlight[key];
	if (flight) return flight;
	var run = ctx.mint(remotePath, contentType).then(function (url) {
		previewUrlCache[key] = { url: url, at: Date.now() };
		delete previewInFlight[key];
		return url;
	}, function (e) {
		delete previewInFlight[key];
		throw e;
	});
	previewInFlight[key] = run;
	return run;
}

/**
 * Hydrate every un-claimed preview <img> in the given list.
 *
 * Idempotent: an element is claimed by its own data-bq-img-state, so a full
 * re-render, a Vue patch, or two calls in one frame cannot mint twice. The
 * caller decides WHICH elements to pass, so a view can move from
 * querySelectorAll to an IntersectionObserver without an engine change.
 */
export function hydrateImagePreviews(imgs: ArrayLike<PreviewImageEl>, ctx: ImagePreviewContext): void {
	for (var i = 0; i < imgs.length; i++) hydrateOne(imgs[i], ctx);
}

function hydrateOne(img: PreviewImageEl, ctx: ImagePreviewContext): void {
	if (img.getAttribute('data-bq-img-state')) return;   // already claimed
	var path = img.getAttribute('data-bq-img-path');
	var type = img.getAttribute('data-bq-img-type') || '';
	if (!path) { img.setAttribute('data-bq-img-state', 'error'); return; }
	img.setAttribute('data-bq-img-state', 'loading');

	img.addEventListener('load', function () {
		img.setAttribute('data-bq-img-state', 'ready');
		if (ctx.onLoad) ctx.onLoad(path as string);
	});
	img.addEventListener('error', function () { onImageError(img, ctx, path as string, type); });

	var warm = peekImagePreviewUrl(ctx, path);
	if (warm) { img.setAttribute('src', warm); return; }   // same frame, no flash

	resolveImagePreviewUrl(ctx, path, type).then(function (url) {
		// The element may have been torn out and replaced while we waited.
		if (img.getAttribute('data-bq-img-state') !== 'loading') return;
		img.setAttribute('src', url);
	}, function (e) {
		img.setAttribute('data-bq-img-state', 'error');
		if (ctx.onError) ctx.onError(path as string, e);
	});
}

/**
 * One retry, then the caption chip is the answer.
 *
 * A presign that died between the mint and the paint is the common failure and
 * minting again fixes it. A deleted file, a wrong path or a 403 is not fixed by
 * retrying, so the second failure is final and the image stays hidden.
 */
function onImageError(img: PreviewImageEl, ctx: ImagePreviewContext, path: string, type: string): void {
	if (img.getAttribute('data-bq-img-retry') === '1') {
		img.setAttribute('data-bq-img-state', 'error');
		if (ctx.onError) ctx.onError(path, new Error('image preview failed to load'));
		return;
	}
	img.setAttribute('data-bq-img-retry', '1');
	delete previewUrlCache[cacheKey(ctx.scope, path)];
	img.removeAttribute('src');
	resolveImagePreviewUrl(ctx, path, type).then(function (url) {
		img.setAttribute('src', url);
	}, function (e) {
		img.setAttribute('data-bq-img-state', 'error');
		if (ctx.onError) ctx.onError(path, e);
	});
}
